%% 入射角 
%% 计算太阳赤纬角delta 
% 输入：D 为以春分作为第0 天起算的天数 
%D = 31; % 4 月21 日对应的天数 
%%输入D 得到R 
% R=Main(D); 
D=[-59 -28 0 31 61 92 122 153 184 214 245 275 ]; 
R_total=[]; 
for i=2:1:size(D,1) 
 R=Main(D(i)); 
